#include "ComponentPath.h"

#include <cassert>
#include <map>
#include <string>
#include <unordered_map>

// Minimal stub implementations (standalone syntax/logic check only).
namespace OpenSim {
ComponentPath::ComponentPath() = default;
ComponentPath::ComponentPath(std::string path) : _path{std::move(path)} {}
ComponentPath::ComponentPath(const std::vector<std::string>&, bool) {}
bool ComponentPath::operator==(const ComponentPath& o) const { return _path == o._path; }
bool ComponentPath::operator!=(const ComponentPath& o) const { return _path != o._path; }
bool ComponentPath::operator<(const ComponentPath& o) const { return _path < o._path; }
OpenSim::ComponentPath OpenSim::ComponentPath::root() { return ComponentPath{"/"}; }
bool ComponentPath::empty() const { return _path.empty(); }
void ComponentPath::clear() { _path.clear(); }
char ComponentPath::getSeparator() const { return '/'; }
const std::string& ComponentPath::getInvalidChars() const { static std::string s{"\\*+ \t\n/"}; return s; }
ComponentPath ComponentPath::formAbsolutePath(const ComponentPath&) const { return {}; }
ComponentPath ComponentPath::formRelativePath(const ComponentPath&) const { return {}; }
ComponentPath ComponentPath::getParentPath() const { return {}; }
std::string ComponentPath::getParentPathString() const { return {}; }
std::string ComponentPath::getSubcomponentNameAtLevel(size_t) const { return {}; }
std::string ComponentPath::getComponentName() const { return {}; }
const std::string& ComponentPath::toString() const { return _path; }
bool ComponentPath::isAbsolute() const { return !_path.empty() && _path[0] == '/'; }
size_t ComponentPath::getNumPathLevels() const { return {}; }
void ComponentPath::pushBack(const std::string&) {}
bool ComponentPath::isLegalPathElement(const std::string&) const { return true; }
}

using OpenSim::ComponentPath;

int main() {
    ComponentPath p{"/a/b"};
    assert(!p.empty());
    p.clear();
    assert(p.empty());
    assert(p.toString() == "");
    assert(ComponentPath::root().toString() == "/");

    assert(ComponentPath{"/a"} < ComponentPath{"/a/b"});
    assert(!(ComponentPath{"/a"} < ComponentPath{"/a"}));

    std::map<ComponentPath, int> m;
    m[ComponentPath{"/a/b"}] = 1;
    m[ComponentPath{"/a/c"}] = 2;
    assert(m.size() == 2);
    assert(m[ComponentPath{"/a/b"}] == 1);

    std::unordered_map<ComponentPath, int> um;
    um[ComponentPath{"/a/b"}] = 1;
    um[ComponentPath{"/a/c"}] = 2;
    assert(um.size() == 2);
    assert(um.count(ComponentPath{"/a/b"}) == 1);
    assert(um.count(ComponentPath{"/a/d"}) == 0);

    assert(std::hash<ComponentPath>{}(ComponentPath{"/a/b"}) ==
           std::hash<ComponentPath>{}(ComponentPath{"/a/b"}));
    return 0;
}

