#include <cmath>
#include <cstddef>
#include <vector>

double sinc(double x) { return x == 0.0 ? 1.0 : std::sin(x) / x; }
double hamming(int k, int M) { return 0.54 - 0.46 * std::cos(2 * M_PI * (k + M) / (2.0 * M + 1.0)); }

int BandpassFIR(int M, double T, double f1, double f2, int N, double* sig, double* sigf) {
    size_t size;
    int i, j;
    int n, k;
    double w1, w2, x1, x2;
    std::vector<double> s;

    if (M + M > N) return -1;

    size = N + M + M;
    s.resize(size);

    w1 = 2 * M_PI * f1;
    w2 = 2 * M_PI * f2;

    for (i = 0, j = M; i < M; i++, j--) s[i] = sig[j];
    for (i = M, j = 0; i < M + N; i++, j++) s[i] = sig[j];
    for (i = M + N, j = N - 2; i < M + M + N; i++, j--) s[i] = sig[j];

    double sum_coef, coef;
    for (n = 0; n < N; n++) {
        sum_coef = 0.0;
        sigf[n] = 0.0;
        for (k = -M; k <= M; k++) {
            x1 = (double)k * w1 * T;
            x2 = (double)k * w2 * T;
            coef = (sinc(x2) * T * w2 / M_PI - sinc(x1) * T * w1 / M_PI) * hamming(k, M);
            sigf[n] = sigf[n] + coef * s[M + n - k];
            sum_coef = sum_coef + coef;
        }
        sigf[n] = sigf[n] / sum_coef;
    }
    return 0;
}

#include <cassert>
static void timeSeriesReplica() {
    const std::vector<double> timeCol = {0.0, 1.0, 2.0, 3.0};
    int last = static_cast<int>(timeCol.size()) - 1;

    auto nearest = [&](const double time) -> size_t {
        size_t idx = 0;
        for (size_t i = 0; i < timeCol.size(); ++i) {
            if (timeCol[i] <= time) idx = i;
        }
        return idx;
    };

    const double time = 1.25;
    double eps = 1e-9;

    // decrementing candidate: time after nearest (should decrement and stay >= 0)
    ptrdiff_t candidate = (ptrdiff_t)nearest(time + 1.0);
    if (timeCol[candidate] > time + eps) candidate--;
    assert(candidate >= 0);
    last = (int)candidate;

    // underflow case: candidate would go below zero, now caught by check
    ptrdiff_t candidate2 = 0;
    if (timeCol[candidate2] > timeCol[0] + 100.0 + eps) candidate2--;
    assert((candidate2 < 0) == true); // now valid with signed type

    (void)last;
}

int main() {
    double sig[8] = {1, 2, 3, 4, 5, 6, 7, 8};
    double sigf[8] = {0};
    assert(BandpassFIR(2, 0.1, 1.0, 5.0, 8, sig, sigf) == 0);
    assert(sigf[0] != 0.0);
    timeSeriesReplica();
    return 0;
}

