TEST_CASE("MuscleFirstOrderActivationDynamicModel derivative continuity") {

    double amin = 0.01;
    double minTol = 0.5;
    double taylorMult = 2.0000001;

    SECTION("w.r.t. excitation and constant activation") {
        MuscleFirstOrderActivationDynamicModel actMdl;

        // Generate a range of activation values
        SimTK::Vector actV(10);
        for (int i = 0; i < actV.size(); i++) {
            actV(i) = (1 - amin) * ((double)i) / ((double)actV.size() - 1.0) + amin;
        }

        // Generate a detailed range of excitations
        SimTK::Vector uV(100);
        for (int i = 0; i < uV.size(); i++) {
            uV(i) = ((double)i) / ((double)uV.size() - 1.0);
        }

        SimTK::Vector dx(uV.size()), d2x(uV.size()), d3x(uV.size());
        dx = 0; d2x = 0; d3x = 0;
        SimTK::Matrix xM(uV.size(), 2);

        bool continuous = false;
        double tmp = 0;
        double maxDxDiff = 0;

        for (int i = 0; i < actV.size(); i++) {
            for (int j = 0; j < uV.size(); j++) {
                xM(j, 0) = actV(i);
                xM(j, 1) = uV(j);
                dx(j) = actMdl.calcDerivative(actV(i), uV(j));
            }
            d2x = calcCentralDifference(xM(1), dx, true);

            for (int j = 1; j < uV.size(); j++) {
                tmp = abs(d2x(j) - d2x(j - 1));
                if (tmp > maxDxDiff)
                    maxDxDiff = tmp;
            }

            d3x = calcCentralDifference(xM(1), d2x, true);

            continuous = isFunctionContinuous(xM(1), dx, d2x, d3x, minTol, taylorMult);
            CHECK(continuous);
        }
        INFO("PASSED: with an allowable error of minTol of " << minTol
                << " or " << taylorMult
                << " x the next Taylor series term. These values are reasonable "
                   "given the elbow in the function and the maximum difference in "
                   "slope of " << maxDxDiff);
    }

