    double stepStart = 0.2;
    double stepEnd   = 0.5;
    double amin = 0.01;

    double tauA   = 0.01;
    double tauD   = 0.04;



    ////////////////////////////
    //generate a step input
    ////////////////////////////

    SimTK::Vector timeV(pts);
    SimTK::Matrix xM(pts,2);

    for(int i=0; i<pts; i++){
        timeV(i) = ((double)i)/((double)pts-1.0);
        xM(i,0) = amin;
        if( timeV(i)<=stepStart || timeV(i)>=stepEnd ){
