            && (ft90>rt90) && (ft90>stepEnd) && (ft10>ft90));
    CHECK(normRiseTime == Approx(3).margin(0.3));
    CHECK(normFallTime == Approx(2.17).margin(0.2));

    INFO("PASSED: with a normalized 10-90 percent rise time of "
            << normRiseTime << "\n"
            "         and a normalized 90-10 percent fall time of "
            << normFallTime);
}

