/** TypeHelper specialization for SimTK::CoordinateDirection.
A SimTK::CoordinateDirection is serialized as the axis letter of the 
coordinate axis ('X', 'Y' or 'Z') optionally preceded by a '+' or '-' sign to 
indicate the direction along that axis (e.g. '+X' denotes positive X and '-Y' 
denotes negative Y). If no sign is provided the positive direction is used. **/
template<> struct Property<SimTK::CoordinateDirection>::TypeHelper  {
    static const bool IsObjectType = false;
    static SimpleProperty<SimTK::CoordinateDirection>* 
        create(const std::string& name, bool isOne);
