template<> inline bool SimpleProperty<std::string>::
readSimplePropertyFromStream(std::istream& in)
{
    if(this->getMaxListSize()==1)
    {
        std::istringstream& instream = (std::istringstream&)(in);
        values.clear();
        values.push_back(instream.str());
        return true;
   }
   else
       return SimTK::readUnformatted(in, values);
}

// We have to provide specializations for SimTK::CoordinateDirection because
// read/write unformatted would not know how to convert to and from a string
// representation consisting of a coordinate axis letter (X, Y or Z) with an
// optional leading '+' or '-' sign to indicate direction.
namespace {
// Serialize a SimTK::CoordinateDirection as an axis letter optionally preceded
// by a '+' or '-' sign (e.g. "+X", "-Y").
inline std::string coordinateDirectionToString(
        const SimTK::CoordinateDirection& direction)
{
    char axisChar = direction.getAxis() == SimTK::XAxis ? 'X'
                  : direction.getAxis() == SimTK::YAxis ? 'Y'
                  : 'Z';
    std::string out;
    if (direction.getDirection() < 0) out += '-';
    else out += '+';
    out += axisChar;
    return out;
}
// Parse a SimTK::CoordinateDirection from an axis letter with an optional
// leading '+' or '-' sign. Returns false if the input is not valid. On
// success the parsed direction is written to \a direction.
inline bool readCoordinateDirectionFromString(const std::string& token,
        SimTK::CoordinateDirection& direction)
{
    std::size_t pos = 0;
    int sign = 1;
    if (pos < token.size() &&
            (token[pos] == '+' || token[pos] == '-')) {
        if (token[pos] == '-') sign = -1;
        ++pos;
    }
    if (pos + 1 != token.size()) return false;
    const char axisChar = static_cast<char>(std::tolower(
        static_cast<unsigned char>(token[pos])));
    SimTK::CoordinateAxis axis;
    if (axisChar == 'x') axis = SimTK::XAxis;
    else if (axisChar == 'y') axis = SimTK::YAxis;
    else if (axisChar == 'z') axis = SimTK::ZAxis;
    else return false;
    direction = SimTK::CoordinateDirection(axis, sign);
    return true;
}
} // anonymous namespace

template<> inline bool SimpleProperty<SimTK::CoordinateDirection>::
readSimplePropertyFromStream(std::istream& in)
{
    SimTK::Array_<SimTK::CoordinateDirection> valuesBackup = values;
    values.clear();
    bool ok = true;
    while (in >> std::ws && !in.eof()) {
        std::string token;
        in >> token;
        if (in.fail()) { ok = false; break; }
        SimTK::CoordinateDirection direction;
        if (!readCoordinateDirectionFromString(token, direction)) {
            ok = false;
            break;
        }
        values.push_back(direction);
    }
    if (!ok) values = valuesBackup;
    return ok;
}

template<> inline void SimpleProperty<SimTK::CoordinateDirection>::
writeSimplePropertyToStream(std::ostream& o) const
{
    for (int i = 0; i < values.size(); ++i) {
        if (i > 0) o << ' ';
        o << coordinateDirectionToString(values[i]);
    }
}

