 * See the License for the specific language governing permissions and        *
 * limitations under the License.                                             *
 * -------------------------------------------------------------------------- */

// INCLUDE
#include <OpenSim/Simulation/Model/PhysicalFrame.h>
#include <OpenSim/Simulation/Model/Station.h>

#include "SimTKcommon/internal/CoordinateAxis.h"

namespace OpenSim {

//=============================================================================
//=============================================================================
/**
 * This class is a PhysicalFrame whose position and orientation are defined
 * by the locations of a set of Station%s measured in a common (base) PhysicalFrame.
 * Unlike a PhysicalOffsetFrame, which requires the user to specify a fixed
 * offset transform (i.e., a position and orientation pair) with respect to a
 * parent PhysicalFrame, the transform of a %StationDefinedFrame is computed
 * from the locations of Stations that are already present in the Model. This
 * is useful for defining anatomical frames that are specified in terms of
 * landmarks (for example, ISB's Grood and Suntay style frame definitions), as
 * an alternative to OffsetFrame%s which require the mapping to be worked out
 * and hard-coded as a (position, orientation) tuple.
 *
 * A %StationDefinedFrame is defined by:
 * - three non-co-located Stations, `point_a`, `point_b` and `point_c`, which
 *   span a (non-degenerate) triangle, and
 * - two "registrations", `ab_axis` and `ab_x_ac_axis`, that map two computed
 *   unit vectors onto two of the resulting frame's coordinate axes.
 *
 * Optionally, a fourth Station, `origin_point`, determines the location of the
 * resulting frame's origin. If `origin_point` is not specified it defaults to
 * `point_a`.
 *
 * The frame is computed as follows:
 * - `ab_axis_vec = normalize(point_b - point_a)`
 * - `ab_x_ac_axis_vec = normalize((point_b - point_a) X (point_c - point_a))`
 * - the two vectors above are mapped onto (resp.) the coordinate axes
 *   registered in the `ab_axis` and `ab_x_ac_axis` properties (with an
 *   optional sign to indicate direction along that axis), and
 * - the third axis is the cross product of the two mapped vectors chosen so
 *   that the result is a right-handed orthonormal coordinate system.
 * - the position of the frame's origin is the location of the `origin_point`
 *   Station.
 *
 * For example, a %StationDefinedFrame whose `ab_axis` is "+X" and whose
 * `ab_x_ac_axis` is "+Z" will have its frame X-axis aligned with the unit
 * vector (point_b - point_a), its frame Z-axis aligned with the unit vector
 * (point_b - point_a) X (point_c - point_a), and its frame Y-axis aligned
 * with Z X X so that the frame is right-handed.
 *
 * The registration properties are of type SimTK::CoordinateDirection and are
 * serialized in .osim files as the coordinate axis letter ('X', 'Y' or 'Z')
 * optionally preceded by a '+' or '-' sign indicating the direction along that
 * axis. If no sign is provided the positive direction is used. For example,
 * "<ab_axis>+X</ab_axis>" and "<ab_x_ac_axis>-Y</ab_x_ac_axis>".
 *
 * All of the point Stations must be attached (directly or indirectly, through
 * PhysicalOffsetFrame%s) to PhysicalFrames that share the same base Frame. The
 * %StationDefinedFrame is then fixed (rigid) in that base Frame and shares its
 * underlying Simbody MobilizedBody.
 *
 * <h3>Known limitations</h3>
 * - All of the point Stations must be attached to Frames that share the same
 *   base Frame (i.e., the landmark triangle has to be rigid).
 * - Chaining dependent frames (e.g., Ground <-- StationDefinedFrame <--
 *   StationDefinedFrame <-- PhysicalOffsetFrame <-- ...) may not work correctly
 *   due to limitations of the graph traversal used to order Frames during
 *   system construction.
 * - The %StationDefinedFrame cannot be used as the child frame of a Joint in
 *   some configurations (for example when the Station%s that define it are
 *   not attached to Ground or to the joint's child body).
 *
 * @author Carmichael Ong, Claude T. Moorman
 */
class OSIMSIMULATION_API StationDefinedFrame : public PhysicalFrame {
OpenSim_DECLARE_CONCRETE_OBJECT(StationDefinedFrame, PhysicalFrame);

public:
    //==============================================================================
    // PROPERTIES
    //==============================================================================
    OpenSim_DECLARE_PROPERTY(ab_axis, SimTK::CoordinateDirection,
        "The coordinate direction ('+X', '-Y', 'Z', etc.) of the resulting "
        "frame's axes onto which the unit vector from 'point_a' to 'point_b' "
        "is mapped.");
    OpenSim_DECLARE_PROPERTY(ab_x_ac_axis, SimTK::CoordinateDirection,
        "The coordinate direction ('+X', '-Y', 'Z', etc.) of the resulting "
        "frame's axes onto which the unit vector "
        "(point_b - point_a) X (point_c - point_a) is mapped.");

    //==============================================================================
    // SOCKETS
    //==============================================================================
    OpenSim_DECLARE_SOCKET(point_a, Station,
        "A Station that defines the first point of the triangle used to "
        "define this frame.");
    OpenSim_DECLARE_SOCKET(point_b, Station,
        "A Station that defines the second point of the triangle used to "
        "define this frame.");
    OpenSim_DECLARE_SOCKET(point_c, Station,
        "A Station that defines the third point of the triangle used to "
        "define this frame.");
    OpenSim_DECLARE_SOCKET(origin_point, Station,
        "A Station that defines the origin of this frame. If unspecified, "
        "'point_a' is used as the origin.");

    //--------------------------------------------------------------------------
    // CONSTRUCTION
    //--------------------------------------------------------------------------
    /** Default constructor. */
    StationDefinedFrame();

    /** Convenience constructor that takes the three point Stations that define
    this frame.
    @param[in] name    Name of this Frame.
    @param[in] pointA  Station defining point_a of this frame.
    @param[in] pointB  Station defining point_b of this frame.
    @param[in] pointC  Station defining point_c of this frame. */
    StationDefinedFrame(const std::string& name,
                        const Station& pointA,
                        const Station& pointB,
                        const Station& pointC);

    /** Convenience constructor that takes the three point Stations that define
    this frame along with a Station that defines its origin.
    @param[in] name        Name of this Frame.
    @param[in] pointA      Station defining point_a of this frame.
    @param[in] pointB      Station defining point_b of this frame.
    @param[in] pointC      Station defining point_c of this frame.
    @param[in] originPoint Station defining the origin of this frame. */
    StationDefinedFrame(const std::string& name,
                        const Station& pointA,
                        const Station& pointB,
                        const Station& pointC,
                        const Station& originPoint);

    virtual ~StationDefinedFrame() {}

    //=============================================================================
    // API
    //=============================================================================
    /** Get the Station that defines point_a of this frame. */
    const Station& getPointA() const;
    /** Get the Station that defines point_b of this frame. */
    const Station& getPointB() const;
    /** Get the Station that defines point_c of this frame. */
    const Station& getPointC() const;
    /** Get the Station that defines the origin of this frame. If the
    'origin_point' socket is not connected, point_a is used as the origin. */
    const Station& getOriginPoint() const;

    /** Set the Station that defines point_a of this frame. */
    void setPointA(const Station& station) { connectSocket_point_a(station); }
    /** Set the Station that defines point_b of this frame. */
    void setPointB(const Station& station) { connectSocket_point_b(station); }
    /** Set the Station that defines point_c of this frame. */
    void setPointC(const Station& station) { connectSocket_point_c(station); }
    /** Set the Station that defines the origin of this frame. If this is not
    set, 'point_a' is used as the origin. */
    void setOriginPoint(const Station& station)
    {   connectSocket_origin_point(station); }

    /** Set the coordinate directions onto which the computed vectors are
    mapped. The two directions must be along different axes. */
    void setAxes(const SimTK::CoordinateDirection& abAxis,
            const SimTK::CoordinateDirection& abXacAxis);

    /** Get the coordinate direction onto which the unit vector
    (point_b - point_a) is mapped. */
    const SimTK::CoordinateDirection& getABAxis() const
    {   return get_ab_axis(); }
    /** Get the coordinate direction onto which the unit vector
    (point_b - point_a) X (point_c - point_a) is mapped. */
    const SimTK::CoordinateDirection& getABXACAxis() const
    {   return get_ab_x_ac_axis(); }

private:
    //=============================================================================
    // Frame INTERFACE
    //=============================================================================
    /** The transform X_GF of this StationDefinedFrame (F) in Ground (G). */
    SimTK::Transform
        calcTransformInGround(const SimTK::State& state) const override;

    /** The spatial velocity {omega; v} of this StationDefinedFrame in Ground. */
    SimTK::SpatialVec
        calcVelocityInGround(const SimTK::State& state) const override;

    /** The spatial acceleration {alpha; a} for this StationDefinedFrame in
    Ground. */
    SimTK::SpatialVec
        calcAccelerationInGround(const SimTK::State& state) const override;

    /** The base Frame of this StationDefinedFrame, which is the base Frame
    shared by the PhysicalFrames its point Stations are attached to. */
    const Frame& extendFindBaseFrame() const override;
    /** The Transform of this StationDefinedFrame in its base Frame. */
    SimTK::Transform extendFindTransformInBaseFrame() const override;

    //=============================================================================
    // COMPONENT INTERFACE
    //=============================================================================
    void extendFinalizeFromProperties() override;
    void extendConnectToModel(Model& model) override;
    void extendAddToSystem(SimTK::MultibodySystem& system) const override;

    void setNull();
    void constructProperties();

    /** Compute the Transform X_BF of this StationDefinedFrame (F) in its base
    Frame (B), along with validation that the points form a valid, non-
    degenerate triangle and that the registered axes are distinct. */
    SimTK::Transform computeTransformInBase() const;

    /** Ensure the point Stations' own connections (e.g., their parent Frame)
    are made so that this frame and its dependents can query them. */
    void connectPointStations(Model& model);

//=============================================================================
};  // END of class StationDefinedFrame
//=============================================================================
//=============================================================================

} // end of namespace OpenSim

#endif // OPENSIM_STATION_DEFINED_FRAME_H_

