// SETUP
//=============================================================================
void StationDefinedFrame::setNull()
{
    setAuthors("Carmichael Ong, Claude T. Moorman");
}

void StationDefinedFrame::constructProperties()
{
    // Default registrations map the ab vector onto +X and the cross product
    // (point_b - point_a) X (point_c - point_a) onto +Z.
    constructProperty_ab_axis(SimTK::XAxis);
    constructProperty_ab_x_ac_axis(SimTK::ZAxis);
}

//=============================================================================
// API
//=============================================================================
const Station& StationDefinedFrame::getPointA() const
{
    return getSocket<Station>("point_a").getConnectee();
}

const Station& StationDefinedFrame::getPointB() const
{
    return getSocket<Station>("point_b").getConnectee();
}

const Station& StationDefinedFrame::getPointC() const
{
    return getSocket<Station>("point_c").getConnectee();
}

const Station& StationDefinedFrame::getOriginPoint() const
{
    const AbstractSocket& originSocket = getSocket("origin_point");
    if (!originSocket.isConnected() && originSocket.getConnecteePath().empty())
        return getPointA();
    return getSocket<Station>("origin_point").getConnectee();
}

void StationDefinedFrame::setAxes(const SimTK::CoordinateDirection& abAxis,
        const SimTK::CoordinateDirection& abXacAxis)
{
    set_ab_axis(abAxis);
    set_ab_x_ac_axis(abXacAxis);
}

//=============================================================================
// PHYSICALFRAME INTERFACE
//=============================================================================
SimTK::Transform StationDefinedFrame::calcTransformInGround(
        const SimTK::State& state) const
{
    return findBaseFrame().getTransformInGround(state)*computeTransformInBase();
}

SimTK::SpatialVec StationDefinedFrame::calcVelocityInGround(
        const SimTK::State& state) const
{
    // This frame is rigidly attached to its base frame, so its velocity
    // differs from the base frame's velocity only by the translational
    // velocity due to the base frame's angular velocity and the distance
    // between the two frames' origins.
    const Frame& base = findBaseFrame();
    const SimTK::Vec3 r =
        base.getTransformInGround(state).R()*computeTransformInBase().p();
    SimTK::SpatialVec V = base.getVelocityInGround(state);
    V[1] += V[0] % r;

    return V;
}

SimTK::SpatialVec StationDefinedFrame::calcAccelerationInGround(
        const SimTK::State& state) const
{
    // This frame is rigidly attached to its base frame, so its acceleration
    // differs from the base frame's acceleration only by the rigid body terms
    // due to the distance between the two frames' origins.
    const Frame& base = findBaseFrame();
    const SimTK::Vec3 r =
        base.getTransformInGround(state).R()*computeTransformInBase().p();
    const SimTK::SpatialVec& V = base.getVelocityInGround(state);
    SimTK::SpatialVec A = base.getAccelerationInGround(state);
    A[1] += A[0] % r + V[0] % (V[0] % r);

    return A;
}

const Frame& StationDefinedFrame::extendFindBaseFrame() const
{
    // The base of this frame is the base Frame shared by the Frames that its
    // point Stations are attached to. The requirement that the point Stations
    // all share the same base Frame is validated in
    // StationDefinedFrame::extendConnectToModel().
    return getPointA().getParentFrame().findBaseFrame();
}

SimTK::Transform StationDefinedFrame::
    extendFindTransformInBaseFrame() const
{
    return computeTransformInBase();
}

//=============================================================================
// COMPONENT INTERFACE
//=============================================================================
void StationDefinedFrame::extendFinalizeFromProperties()
{
    Super::extendFinalizeFromProperties();

    // If an origin point is not specified then point_a is used as the origin
    // of this frame.
    if (getSocket("origin_point").getConnecteePath().empty()) {
        updSocket("origin_point").setConnecteePath(
            getSocket("point_a").getConnecteePath());
    }

    // The two registered axes must be along different coordinate axes; if the
    // registration collapsed onto the same axis the resulting frame would not
    // be a valid rotation matrix.
    const SimTK::CoordinateDirection abDir = get_ab_axis();
    const SimTK::CoordinateDirection crossDir = get_ab_x_ac_axis();
    OPENSIM_THROW_IF_FRMOBJ(abDir.getAxis() == crossDir.getAxis(), Exception,
        "StationDefinedFrame '" + getName() + "' requires that the axes "
        "registered in the 'ab_axis' and 'ab_x_ac_axis' properties be along "
        "different coordinate axes. Please set distinct axes.");
}

void StationDefinedFrame::extendConnectToModel(Model& model)
{
    Super::extendConnectToModel(model);

    // The point Stations are connectees rather than subcomponents of this
    // frame, so they must be finalized explicitly before we can query the
    // Frames they are attached to.
    connectPointStations(model);

    // All of the point Stations must be attached to Frames that share the
    // same base Frame so that the frame computed from their locations is at
    // rest in a single base Frame.
    const Frame& base = getPointA().getParentFrame().findBaseFrame();
    const Frame& baseB = getPointB().getParentFrame().findBaseFrame();
    const Frame& baseC = getPointC().getParentFrame().findBaseFrame();
    const Frame& baseOrigin = getOriginPoint().getParentFrame().findBaseFrame();
    OPENSIM_THROW_IF_FRMOBJ(&base != &baseB || &base != &baseC
                            || &base != &baseOrigin, Exception,
        "StationDefinedFrame '" + getName() + "' requires that all of its "
        "point Stations (point_a, point_b, point_c, origin_point) be attached "
        "to Frames that share the same base Frame. The computed Frame is only "
        "rigidly fixed to a single base Frame when the landmark triangle "
        "defining it is rigid.");
}

void StationDefinedFrame::extendAddToSystem(SimTK::MultibodySystem& system) const
{
    Super::extendAddToSystem(system);

    // This frame is rigidly attached to the Frames that its point Stations
    // are attached to, so it shares their underlying Simbody MobilizedBody.
    setMobilizedBodyIndex(getPointA().getParentFrame().getMobilizedBodyIndex());
}

void StationDefinedFrame::connectPointStations(Model& model)
{
    // Making the connections of the point Stations is a no-op if they are
    // already connected.
    const_cast<Station&>(getPointA()).finalizeConnections(model);
    const_cast<Station&>(getPointB()).finalizeConnections(model);
    const_cast<Station&>(getPointC()).finalizeConnections(model);
    const_cast<Station&>(getOriginPoint()).finalizeConnections(model);
}

//=============================================================================
// UTILITY
//=============================================================================
SimTK::Transform StationDefinedFrame::computeTransformInBase() const
{
    // Locations of the point Stations expressed in this frame's base frame.
    const SimTK::Vec3 pA =
        getPointA().getParentFrame().findTransformInBaseFrame()
        *getPointA().get_location();
    const SimTK::Vec3 pB =
        getPointB().getParentFrame().findTransformInBaseFrame()
        *getPointB().get_location();
    const SimTK::Vec3 pC =
        getPointC().getParentFrame().findTransformInBaseFrame()
        *getPointC().get_location();
    const SimTK::Vec3 pOrigin =
        getOriginPoint().getParentFrame().findTransformInBaseFrame()
        *getOriginPoint().get_location();

    // The points must form a non-degenerate triangle.
    const SimTK::Vec3 ab = pB - pA;
    const SimTK::Vec3 ac = pC - pA;
    OPENSIM_THROW_IF_FRMOBJ(ab.norm() <= SimTK::SignificantReal, Exception,
        "StationDefinedFrame '" + getName() + "' has degenerate geometry: the "
        "Station(s) 'point_a' and 'point_b' cannot be co-located since the "
        "vector (point_b - point_a) is undefined.");
    const SimTK::Vec3 abXac = ab % ac;
    OPENSIM_THROW_IF_FRMOBJ(abXac.norm() <= SimTK::SignificantReal, Exception,
        "StationDefinedFrame '" + getName() + "' has degenerate geometry: the "
        "Station(s) 'point_a', 'point_b' and 'point_c' cannot be co-located or "
        "collinear since the vector (point_b - point_a) X (point_c - point_a) "
        "is undefined.");

    // The two registered axes must be along different coordinate axes.
    const SimTK::CoordinateDirection abDir = get_ab_axis();
    const SimTK::CoordinateDirection crossDir = get_ab_x_ac_axis();
    OPENSIM_THROW_IF_FRMOBJ(abDir.getAxis() == crossDir.getAxis(), Exception,
        "StationDefinedFrame '" + getName() + "' requires that the axes "
        "registered in the 'ab_axis' and 'ab_x_ac_axis' properties be along "
        "different coordinate axes. Please set distinct axes.");

    // The unit vectors mapped onto the frame's axes are:
    //     ab_axis_vec       = normalize(point_b - point_a)
    //     ab_x_ac_axis_vec  = normalize((point_b - point_a) X (point_c - point_a))
    // and the third axis is the cross product of the two such that the result
    // is a right-handed coordinate system.
    SimTK::Vec3 columns[3];
    columns[static_cast<int>(abDir.getAxis())] =
        static_cast<double>(abDir.getDirection())*ab.normalize();
    columns[static_cast<int>(crossDir.getAxis())] =
        static_cast<double>(crossDir.getDirection())*abXac.normalize();
    const int thirdIndex =
        3 - static_cast<int>(abDir.getAxis())
            - static_cast<int>(crossDir.getAxis());
    columns[thirdIndex] = columns[(thirdIndex + 1) % 3]
                          % columns[(thirdIndex + 2) % 3];

    SimTK::Rotation R;
    for (int i = 0; i < 3; ++i) {
        R.setColumn(SimTK::CoordinateAxis::getCoordinateAxis(i),
                    SimTK::UnitVec3(columns[i]));
    }

    // TODO: is this the right tolerance?
    OPENSIM_THROW_IF_FRMOBJ(!R.isValidRotation(), Exception,
        "StationDefinedFrame '" + getName() + "' did not produce a valid "
        "rotation matrix; the resulting coordinate system must be "
        "right-handed.");

    return SimTK::Transform(R, pOrigin);
}

