// Now include all remaining Components beginning with physical Frames
    // since Constraints, Forces and other components can only be applied to
    // PhyicalFrames, which include PhysicalOffsetFrames and
    // StationDefinedFrames. These Frames depend on other Frames that must be
    // added to the System first (e.g., a PhysicalOffsetFrame depends on its
    // parent Frame, and a StationDefinedFrame depends on the Frames its point
    // Stations are attached to). Frames that are part of the multibody tree
    // (i.e., Ground and Body) are ordered by the graph above; the remaining
    // Frames can be listed in any order and may be attached to any other
    // Frame, so we order them with a topological sort to determine a valid
    // order for adding them to the underlying System.
    std::vector<std::reference_wrapper<Frame>> dependentFrames;
    for (Frame& frame : updComponentList<Frame>()) {
        if (dynamic_cast<PhysicalOffsetFrame*>(&frame) ||
            dynamic_cast<StationDefinedFrame*>(&frame)) {
            dependentFrames.push_back(frame);
        }
    }

    // Determine the Frames each dependent Frame depends on. The edges of the
    // dependency graph point from a Frame to the Frames that depend on it.
    std::map<const Frame*, std::vector<const Frame*>> dependents;
    std::map<const Frame*, int> numUnorderedDependencies;
    for (auto& frameRef : dependentFrames) {
        Frame& frame = frameRef.get();

        // The Frame's connections are made here so that its dependencies can
        // be determined in any order.
        frame.finalizeConnections(*this);

        std::vector<const Frame*> frameDependencies;
        if (PhysicalOffsetFrame* pof =
                dynamic_cast<PhysicalOffsetFrame*>(&frame)) {
            frameDependencies.push_back(&pof->getParentFrame());
        }
        else if (StationDefinedFrame* sdf =
                dynamic_cast<StationDefinedFrame*>(&frame)) {
            // A StationDefinedFrame depends on the Frames that its point
            // Stations are attached to. Note that StationDefinedFrame::
            // extendConnectToModel() finalizes the point Stations so their
            // parent Frames can be determined here.
            frameDependencies.push_back(&sdf->getPointA().getParentFrame());
            frameDependencies.push_back(&sdf->getPointB().getParentFrame());
            frameDependencies.push_back(&sdf->getPointC().getParentFrame());
            frameDependencies.push_back(&sdf->getOriginPoint().getParentFrame());
        }

        numUnorderedDependencies[&frame] = 0;
        for (const Frame* dependency : frameDependencies) {
            // Dependencies that are not dependent Frames themselves (e.g.,
            // Ground and Body Frames) are ordered by the multibody graph
            // above, so they do not constrain the ordering here.
            if (!numUnorderedDependencies.count(dependency)) continue;
            dependents[dependency].push_back(&frame);
            ++numUnorderedDependencies[&frame];
        }
    }

    // Topologically sort the dependent Frames (Kahn's algorithm). Using the
    // Frame's order in the ComponentList as the tie-breaker preserves the
    // deterministic order in which Frames were added to the Model.
    std::vector<const Frame*> orderedFrames;
    for (auto& frameRef : dependentFrames) {
        const Frame* frame = &frameRef.get();
        if (numUnorderedDependencies[frame] == 0)
            orderedFrames.push_back(frame);
    }
    for (std::size_t i = 0; i < orderedFrames.size(); ++i) {
        for (const Frame* dependent : dependents[orderedFrames[i]]) {
            if (--numUnorderedDependencies[dependent] == 0)
                orderedFrames.push_back(dependent);
        }
    }

    // If not all the dependent Frames were ordered then the Frames form one
    // or more loops.
    bool framesFormLoop = orderedFrames.size() < dependentFrames.size();
    if (framesFormLoop) {
        std::string loopFrameName;
        for (auto& frameRef : dependentFrames) {
            if (numUnorderedDependencies[&frameRef.get()] > 0) {
                loopFrameName = frameRef.get().getName();
                break;
            }
        }
        OPENSIM_THROW_IF_FRMOBJ(framesFormLoop,
            PhysicalOffsetFramesFormLoop, loopFrameName);
    }

    for (const Frame* frame : orderedFrames) {
        setNextSubcomponentInSystem(*frame);
    }

