//=============================================================================
// INCLUDES
//=============================================================================

#include "Simbody.h"

#include "OpenSim/OpenSim.h"
#include "OpenSim/Simulation/Model/StationDefinedFrame.h"

#include <catch2/catch_all.hpp>

using namespace OpenSim;
using namespace SimTK;

namespace {

//=============================================================================
// UTILITY
//=============================================================================

/** Build a Model that contains a StationDefinedFrame defined by three (and
optionally a fourth origin) Stations placed on the Model's Ground frame. The
Stations are connected directly to Ground. */
void buildModelWithStationsOnGround(Model& model,
        const SimTK::Vec3& pA, const SimTK::Vec3& pB, const SimTK::Vec3& pC,
        const SimTK::CoordinateDirection& abAxis = SimTK::XAxis,
        const SimTK::CoordinateDirection& abXacAxis = SimTK::ZAxis,
        bool withOrigin = false,
        const SimTK::Vec3& pOrigin = SimTK::Vec3(0))
{
    model.setName("StationDefinedFrameTestModel");
    model.setGravity(SimTK::Vec3(0));

    const Ground& ground = model.getGround();

    Station* pointA = new Station(ground, pA);
    pointA->setName("point_a");
    Station* pointB = new Station(ground, pB);
    pointB->setName("point_b");
    Station* pointC = new Station(ground, pC);
    pointC->setName("point_c");
    model.addModelComponent(pointA);
    model.addModelComponent(pointB);
    model.addModelComponent(pointC);

    StationDefinedFrame* sdf = nullptr;
    if (withOrigin) {
        Station* originPoint = new Station(ground, pOrigin);
        originPoint->setName("origin_point");
        model.addModelComponent(originPoint);
        sdf = new StationDefinedFrame(
                "sdf", *pointA, *pointB, *pointC, *originPoint);
    }
    else {
        sdf = new StationDefinedFrame("sdf", *pointA, *pointB, *pointC);
    }
    sdf->setAxes(abAxis, abXacAxis);
    model.addComponent(sdf);
}

/** Check that the given Transform is approximately the identity Transform. */
void requireIdentityTransform(const SimTK::Transform& X, double tol)
{
    INFO("Transform must be approximately the identity transform.");
    CHECK((X.p() - SimTK::Vec3(0)).norm() < tol);
    CHECK(X.R().isSameRotationToWithinAngle(SimTK::Rotation(), tol));
}

/** Check that two Transforms are approximately equal. */
void requireEquivalentTransforms(const SimTK::Transform& X1,
        const SimTK::Transform& X2, double tol)
{
    INFO("Transforms must be approximately equal.");
    CHECK((X1.p() - X2.p()).norm() < tol);
    CHECK(X1.R().isSameRotationToWithinAngle(X2.R(), tol));
}

} // anonymous namespace

//=============================================================================
// TESTS
//=============================================================================

TEST_CASE("StationDefinedFrame computed Transform") {

    SECTION("identity frame with registered axes +X and +Z") {
        // points: a=(0,0,0), b=(1,0,0), c=(0,1,0)
        // ab = (1,0,0) is mapped to +X and
        // ab X ac = (1,0,0) X (0,1,0) = (0,0,1) is mapped to +Z
        // so the resulting frame, with origin at point_a, is the identity.
        Model model;
        buildModelWithStationsOnGround(model,
                SimTK::Vec3(0), SimTK::Vec3(1, 0, 0), SimTK::Vec3(0, 1, 0));

        SimTK::State& s = model.initSystem();
        const auto& sdf =
            model.getComponent<StationDefinedFrame>("/sdf");

        requireIdentityTransform(sdf.getTransformInGround(s), 1e-10);
    }

    SECTION("identity frame with registered axes +Y and +Z") {
        // points: a=(0,0,0), b=(0,1,0), c=(-1,0,0)
        // ab = (0,1,0) is mapped to +Y and
        // ab X ac = (0,1,0) X (-1,0,0) = (0,0,1) is mapped to +Z
        // so the resulting frame, with origin at point_a, is the identity.
        Model model;
        buildModelWithStationsOnGround(model,
                SimTK::Vec3(0), SimTK::Vec3(0, 1, 0), SimTK::Vec3(-1, 0, 0),
                SimTK::YAxis, SimTK::ZAxis);

        SimTK::State& s = model.initSystem();
        const auto& sdf =
            model.getComponent<StationDefinedFrame>("/sdf");

        requireIdentityTransform(sdf.getTransformInGround(s), 1e-10);
    }

    SECTION("non-identity frame with registered axes +X and +Z") {
        // points: a=(0,0,0), b=(1,0,0), c=(0,0,1)
        // ab = (1,0,0) is mapped to +X and
        // ab X ac = (1,0,0) X (0,0,1) = (0,-1,0) is mapped to +Z.
        // The third (Y) axis is Z X X = (0,0,1) so that the frame is
        // right-handed. The resulting rotation matrix has columns
        // X=(1,0,0), Y=(0,0,1), Z=(0,-1,0).
        Model model;
        buildModelWithStationsOnGround(model,
                SimTK::Vec3(0), SimTK::Vec3(1, 0, 0), SimTK::Vec3(0, 0, 1));

        SimTK::State& s = model.initSystem();
        const auto& sdf =
            model.getComponent<StationDefinedFrame>("/sdf");

        SimTK::Rotation expectedR;
        expectedR.setColumn(SimTK::XAxis, SimTK::UnitVec3(1.0, 0.0, 0.0));
        expectedR.setColumn(SimTK::YAxis, SimTK::UnitVec3(0.0, 0.0, 1.0));
        expectedR.setColumn(SimTK::ZAxis, SimTK::UnitVec3(0.0, -1.0, 0.0));

        const SimTK::Transform& X = sdf.getTransformInGround(s);
        CHECK(X.R().isSameRotationToWithinAngle(expectedR, 1e-10));
        CHECK(X.p().norm() < 1e-10);
    }

    SECTION("origin defaults to point_a") {
        Model model;
        buildModelWithStationsOnGround(model,
                SimTK::Vec3(0.3, 0.2, 0.1), SimTK::Vec3(1.3, 0.2, 0.1),
                SimTK::Vec3(0.3, 1.2, 0.1));
        // ab=(1,0,0) mapped to +X; the frame is the identity in ground with
        // its origin at point_a since the default origin is point_a.
        SimTK::State& s = model.initSystem();
        const auto& sdf =
            model.getComponent<StationDefinedFrame>("/sdf");
        const SimTK::Transform& X = sdf.getTransformInGround(s);
        requireIdentityTransform(X, 1e-10);
        CHECK((X.p() - SimTK::Vec3(0.3, 0.2, 0.1)).norm() < 1e-10);
    }

    SECTION("explicit origin point") {
        Model model;
        buildModelWithStationsOnGround(model,
                SimTK::Vec3(0), SimTK::Vec3(1, 0, 0), SimTK::Vec3(0, 1, 0),
                SimTK::XAxis, SimTK::ZAxis, true, SimTK::Vec3(0.4, 0.5, 0.6));
        SimTK::State& s = model.initSystem();
        const auto& sdf =
            model.getComponent<StationDefinedFrame>("/sdf");
        const SimTK::Transform& X = sdf.getTransformInGround(s);
        // Rotation is the identity and the origin coincides with the origin
        // Station.
        requireIdentityTransform(X, 1e-10);
        CHECK((X.p() - SimTK::Vec3(0.4, 0.5, 0.6)).norm() < 1e-10);
    }
}

TEST_CASE("StationDefinedFrame on a Body") {

    Model model;
    model.setName("StationDefinedFrameOnABody");
    model.setGravity(SimTK::Vec3(0));

    // A segment connected to ground by a pin joint that rotates about Z.
    Body* segment = new Body();
    segment->setName("segment");
    segment->setMass(1.0);
    segment->setMassCenter(SimTK::Vec3(0));
    segment->setInertia(SimTK::Inertia(1.0, 1.0, 1.0, 0.0, 0.0, 0.0));
    model.addBody(segment);

    PinJoint* pin = new PinJoint("pin", model.getGround(), *segment);
    model.addJoint(pin);

    // Stations rigidly attached to the segment.
    Station* pointA = new Station(*segment, SimTK::Vec3(0));
    pointA->setName("point_a");
    Station* pointB = new Station(*segment, SimTK::Vec3(1, 0, 0));
    pointB->setName("point_b");
    Station* pointC = new Station(*segment, SimTK::Vec3(0, 1, 0));
    pointC->setName("point_c");
    model.addModelComponent(pointA);
    model.addModelComponent(pointB);
    model.addModelComponent(pointC);

    StationDefinedFrame* sdf = new StationDefinedFrame(
            "sdf", *pointA, *pointB, *pointC);
    model.addComponent(sdf);

    SimTK::State& s = model.initSystem();

    // The StationDefinedFrame is rigidly attached to the segment, so it
    // shares the segment's mobilized body.
    const auto& sdfComp =
        model.getComponent<StationDefinedFrame>("/sdf");
    CHECK(sdfComp.getMobilizedBodyIndex() ==
            segment->getMobilizedBodyIndex());

    // Rotate the segment about its Z axis by 90 degrees.
    model.setCoordinateValue(s, "pin", SimTK::Pi / 2.0);
    model.getSystem().realize(s, SimTK::Stage::Velocity);

    // The frame computed from the Stations is the identity in the segment
    // (its base frame), so its Transform in Ground must match the segment's
    // Transform in Ground.
    const SimTK::Transform& X_segment = segment->getTransformInGround(s);
    const SimTK::Transform& X_sdf = sdfComp.getTransformInGround(s);
    INFO("The frame's Transform in Ground must match its base frame's.");
    CHECK((X_sdf.p() - X_segment.p()).norm() < 1e-10);
    CHECK(X_sdf.R().isSameRotationToWithinAngle(X_segment.R(), 1e-10));

    // Sanity check that the velocity and acceleration accessors work.
    requireEquivalentTransforms(
        SimTK::Transform(sdfComp.getRotationalVelocityInGround(s),
                         sdfComp.getLinearVelocityInGround(s)),
        SimTK::Transform(segment->getAngularVelocityInGround(s),
                         segment->getLinearVelocityInGround(s)),
        1e-10);
}

TEST_CASE("StationDefinedFrame serialization") {

    Model model;
    buildModelWithStationsOnGround(model,
            SimTK::Vec3(0), SimTK::Vec3(1, 0, 0), SimTK::Vec3(0, 1, 0),
            SimTK::NegXAxis, SimTK::ZAxis, true, SimTK::Vec3(0.4, 0.5, 0.6));

    SimTK::State& s = model.initSystem();
    const auto& sdf = model.getComponent<StationDefinedFrame>("/sdf");
    const SimTK::Transform& X = sdf.getTransformInGround(s);

    model.print("testStationDefinedFrame_roundtrip.osim");

    Model reloaded("testStationDefinedFrame_roundtrip.osim");
    const auto& sdf2 =
        reloaded.getComponent<StationDefinedFrame>("/sdf");

    CHECK(sdf2.get_ab_axis().getAxis() == SimTK::XAxis);
    CHECK(sdf2.get_ab_axis().getDirection() == -1);
    CHECK(sdf2.get_ab_x_ac_axis().getAxis() == SimTK::ZAxis);
    CHECK(sdf2.get_ab_x_ac_axis().getDirection() == 1);

    SimTK::State& s2 = reloaded.initSystem();
    const SimTK::Transform& X2 = sdf2.getTransformInGround(s2);

    INFO("Transform of reloaded model must match the original model.");
    requireEquivalentTransforms(X2, X, 1e-10);

    std::remove("testStationDefinedFrame_roundtrip.osim");
}

TEST_CASE("StationDefinedFrame as a joint parent") {

    Model model;
    model.setName("StationDefinedFrameAsJointParent");
    model.setGravity(SimTK::Vec3(0));

    buildModelWithStationsOnGround(model,
            SimTK::Vec3(0), SimTK::Vec3(1, 0, 0), SimTK::Vec3(0, 1, 0));
    auto& sdf = model.updComponent<StationDefinedFrame>("/sdf");

    // Weld a ball to the StationDefinedFrame.
    Body* ball = new Body();
    ball->setName("ball");
    ball->setMass(1.0);
    ball->setMassCenter(SimTK::Vec3(0));
    ball->setInertia(SimTK::Inertia(1.0, 1.0, 1.0, 0.0, 0.0, 0.0));
    model.addBody(ball);

    WeldJoint* weld = new WeldJoint("ball_to_sdf", sdf, *ball);
    model.addJoint(weld);

    SimTK::State& s = model.initSystem();

    // The ball and the StationDefinedFrame are rigidly welded together, so
    // their Transforms in Ground must coincide.
    const SimTK::Transform& X_ball = ball->getTransformInGround(s);
    const SimTK::Transform& X_sdf = sdf.getTransformInGround(s);
    requireEquivalentTransforms(X_ball, X_sdf, 1e-10);

    // The Stations are defined on Ground with a=[0,0,0], b=[1,0,0],
    // c=[0,1,0] and registered axes +X and +Z, so the StationDefinedFrame is
    // the identity in Ground.
    requireIdentityTransform(X_sdf, 1e-10);
}

TEST_CASE("StationDefinedFrame degenerate configurations") {

    SECTION("point_a and point_b are co-located") {
        Model model;
        buildModelWithStationsOnGround(model,
                SimTK::Vec3(0), SimTK::Vec3(0), SimTK::Vec3(1, 0, 0));
        model.setup();
        const auto& sdf = model.getComponent<StationDefinedFrame>("/sdf");
        REQUIRE_THROWS(sdf.findTransformInBaseFrame());
    }

    SECTION("points are collinear") {
        Model model;
        buildModelWithStationsOnGround(model,
                SimTK::Vec3(0), SimTK::Vec3(1, 0, 0), SimTK::Vec3(2, 0, 0));
        model.setup();
        const auto& sdf = model.getComponent<StationDefinedFrame>("/sdf");
        REQUIRE_THROWS(sdf.findTransformInBaseFrame());
    }

    SECTION("registered axes are along the same axis") {
        // +X and -X are along the same axis, which cannot yield a valid
        // right-handed frame.
        Model model;
        buildModelWithStationsOnGround(model,
                SimTK::Vec3(0), SimTK::Vec3(1, 0, 0), SimTK::Vec3(0, 1, 0),
                SimTK::XAxis, SimTK::NegXAxis);
        REQUIRE_THROWS_AS(model.finalizeFromProperties(), OpenSim::Exception);
    }

    SECTION("points are attached to frames with different bases") {
        // point_a is on Ground while point_b and point_c are on a segment
        // that is welded to Ground; the points do not share a base frame.
        Model model;
        model.setName("StationDefinedFrameDifferentBases");
        model.setGravity(SimTK::Vec3(0));

        Body* segment = new Body();
        segment->setName("segment");
        segment->setMass(1.0);
        segment->setMassCenter(SimTK::Vec3(0));
        segment->setInertia(SimTK::Inertia(1.0, 1.0, 1.0, 0.0, 0.0, 0.0));
        model.addBody(segment);
        WeldJoint* weld = new WeldJoint(
            "segment_to_ground", model.getGround(), *segment);
        model.addJoint(weld);

        Station* pointA = new Station(model.getGround(), SimTK::Vec3(0));
        pointA->setName("point_a");
        Station* pointB = new Station(*segment, SimTK::Vec3(1, 0, 0));
        pointB->setName("point_b");
        Station* pointC = new Station(*segment, SimTK::Vec3(0, 1, 0));
        pointC->setName("point_c");
        model.addModelComponent(pointA);
        model.addModelComponent(pointB);
        model.addModelComponent(pointC);

        StationDefinedFrame* sdf = new StationDefinedFrame(
            "sdf", *pointA, *pointB, *pointC);
        model.addComponent(sdf);

        REQUIRE_THROWS_AS(model.setup(), OpenSim::Exception);
    }
}

TEST_CASE("Basic model with StationDefinedFrame loads") {

    // Load the example model file that ships with the tests. The
    // StationDefinedFrame is defined by stations on a body that is welded to
    // Ground with a=[0,0,0], b=[1,0,0], c=[0,1,0] and registered axes +X and
    // +Z, so the frame is the identity in Ground.
    Model model("BasicModelWithStationDefinedFrame.osim");
    SimTK::State& s = model.initSystem();

    const auto& sdf =
        model.getComponent<StationDefinedFrame>("/block_frame");
    requireIdentityTransform(sdf.getTransformInGround(s), 1e-10);
