void StationDefinedFrame::connectPointStations(Model& model)
{
    // The point Stations are connectees rather than subcomponents of this
    // frame, so their own connections (e.g., to the Frames they are attached
    // to) have to be made before this frame's connections can be validated.
    // Making the connections is a no-op if they are already connected.
    auto finalizeStationAndItsFrame = [&model](Station& station) {
        station.finalizeConnections(model);
        const_cast<PhysicalFrame&>(station.getParentFrame()).
            finalizeConnections(model);
    };
    finalizeStationAndItsFrame(const_cast<Station&>(getPointA()));
    finalizeStationAndItsFrame(const_cast<Station&>(getPointB()));
    finalizeStationAndItsFrame(const_cast<Station&>(getPointC()));
    finalizeStationAndItsFrame(const_cast<Station&>(getOriginPoint()));
}

